const upsertSubscriptionTerms = `-- name: UpsertSubscriptionTerms :one

INSERT INTO catalog_subscription_terms (product_id, interval_unit, interval_count, trial_days)
VALUES ($1, $2, $3, $4)
ON CONFLICT (product_id) DO UPDATE
SET interval_unit  = EXCLUDED.interval_unit,
    interval_count = EXCLUDED.interval_count,
    trial_days     = EXCLUDED.trial_days,
    updated_at     = NOW()
RETURNING product_id, interval_unit, interval_count, trial_days, created_at, updated_at
`

type UpsertSubscriptionTermsParams struct {
	ProductID     uuid.UUID `json:"product_id"`
	IntervalUnit  string    `json:"interval_unit"`
	IntervalCount int32     `json:"interval_count"`
	TrialDays     int32     `json:"trial_days"`
}

// Catalog: a subscription product's recurring terms (admin-configured, 1:1)
func (q *Queries) UpsertSubscriptionTerms(ctx context.Context, arg UpsertSubscriptionTermsParams) (CatalogSubscriptionTerm, error) {
	row := q.db.QueryRowContext(ctx, upsertSubscriptionTerms,
		arg.ProductID,
		arg.IntervalUnit,
		arg.IntervalCount,
		arg.TrialDays,
	)
	var i CatalogSubscriptionTerm
	err := row.Scan(
		&i.ProductID,
		&i.IntervalUnit,
		&i.IntervalCount,
		&i.TrialDays,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
